INSERT INTO scholarship (name, provider, description, amount, application_url, min_age, max_age, required_gender, eligible_region, required_military_status, max_income_bracket, min_gpa, min_gpa_basis, requires_disability, required_disability_type, foreigner_eligibility, language_test_type, language_test_min_score, required_special_status, required_special_status_all, excluded_special_status, application_deadline, grade_level, major, excluded_major, admission_track, affiliated_institution, min_credits, min_credits_last_semester, admission_score_condition, headcount, application_period, eligible_university, eligible_college, required_enrollment_status, min_grade, max_grade, required_degree_level, category_l1, category_l2) VALUES
('2026년 2학기 국가장학금 2차 신청', '한국장학재단', '2026년 2학기 국가장학금 2차 신청 일정 안내. 신청대상은 재학생·신입생·편입생·재입학생·복학생 등 모든 학적이며, 재학생은 원칙적으로 1차 신청 기간에만 신청 가능하고 2차 신청자는 재학 중 2회에 한하여 구제신청 자동 적용 및 심사 후 지원 가능. 한국장학재단 홈페이지와 모바일 앱을 통해 신청 가능하며, 1차 기간 신청자는 2차 신청기간 중 신청 수정 또는 신청 취소 후 재신청할 수 없음.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-09-09', NULL, NULL, NULL, 'general', NULL, NULL, NULL, NULL, NULL, '2026. 8. 12.(수) 9시 ~ 2026. 9. 9.(수) 18시', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'national_scholarship'),
('주거안정장학금', '한국장학재단', '주거안정장학금 장학생을 대상으로 장학생 서약서 및 지급요청서 제출 방법과 유의사항을 안내하는 공지. 주거안정장학금은 동일 목적의 주거지원금(국토교통부 청년 주거급여 분리지급, 청년월세 한시 지원사업, 지자체 월세 지원 등)과 중복 수혜 불가하며, 중복 수혜 시 공공재정환수법에 따른 부정청구로 간주되어 장학금 반환 등의 불이익이 발생할 수 있음. 지급요청서 미제출 시 장학생 전체의 장학금 지급이 지연될 수 있어 매달 첫째 주에 지급요청서 작성 요망. 증빙자료는 학생 본인이 5년간 보관 필수.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '목원대학교', NULL, NULL, NULL, NULL, NULL, 'support_fund', 'youth_living_support'),
