('2026년 5·18희망장학생', '5·18기념재단', '가. 장학분야 : 5·18희망장학생 / 나. 장학금액 : 대학생 1명당 100만원, 총 15명 선발 / 다. 선발자격 : 1) 민주화운동 및 국가폭력 피해자 (유)자녀 2) 5·18정신(민주·인권·평화 등) 계승 공동체 기여 활동자', 1000000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-08-12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '총 15명', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'private_foundation'),
('2026년 하반기 울산광역시 대학(원)생 학자금대출 이자지원사업', '울산광역시', '2017년 이후 한국장학재단 신규대출분의 2026년도 상반기(1.~6월) 발생이자를 지원하는 사업', NULL, NULL, NULL, NULL, NULL, '울산', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-08-30', NULL, NULL, NULL, 'general', NULL, NULL, NULL, NULL, NULL, '2026. 7. 31.(금) 09:00 ~ 8. 30.(일) 18:00', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'support_fund', 'youth_living_support'),
('서울인재대학장학금', '서울미래인재재단', '지원성격: 학업장려금(생활비성 장학금) ※ 타 기관 장학금과 중복 수혜 가능. 진로역량: 학업 및 진로 목표를 주도적으로 설계하고 진로역량 개발 의지를 갖춘 자', 2000000, 'www.seoulfuture.or.kr', NULL, NULL, NULL, '서울', NULL, 4, NULL, NULL, NULL, NULL, 'korean_only', NULL, NULL, ARRAY['basic_livelihood_recipient','near_poor'], '{}', '{}', '2026-08-10', '1학년', NULL, NULL, 'general', NULL, NULL, NULL, '성적기준: 1학년 1학기 평점 평균의 백분위(백분율) 성적 90점 이상인 자', '총 228명 내외', '2026.8.3.(월) 10:00 ~ 2026.8.10.(월) 15:00', NULL, NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_external', 'private_foundation'),
('2026년 화성시인재육성재단 「소상공인 장학금」', '화성시인재육성재단', '화성시 지역화폐 가맹점 자녀(대학생) 대상 장학금으로, 본인 또는 부모·친권자 중 1명이 공고일 기준 1년 이상 화성시 계속 거주해야 하며 1인당 100만원을 지역화폐로 지급함', 1000000, 'www.hstree.org', NULL, NULL, NULL, '화성시', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-08-11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '110명', '2026. 7. 20.(월) 10시 ~ 8. 11.(화) 17시', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'local_gov'),
('2026년도 쌍용곰두리장학생', '한국장애인개발원', '선정분야: 성적우수, 예·체능특기, 정보통신특기장학생. 지원내용: 학기당 100만 원 지원(생활보조비로 정액지원), 지원기간: 2026년 2학기 ~ 2027년 1학기. 신청방법: 재학 중인 학교 장학담당부서를 통한 학교장 명의 전자공문 신청(개인 신청 불가, 우편·방문·개인 이메일 접수 불가)', 1000000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-07-31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '총 20명', '2026. 7. 20.(월) ~ 2026. 7. 31.(금)', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'private_foundation'),
('2026년 정읍시민장학재단 우수인재 장학금', '정읍시민장학재단', '공고일(7. 8.) 현재 부 또는 모가 1년 이상 계속하여 정읍시에 주소를 두고 있는 국내 대학(고등교육법 제2조의 학교) 재학생을 대상으로 하는 우수인재 장학금. 접수처는 부 또는 모의 주민등록지(정읍시) 읍·면·동 주민센터이며, 신청자격 등 자세한 사항은 첨부 공고문 참고.', NULL, NULL, NULL, NULL, NULL, '정읍시', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-07-27', NULL, NULL, NULL, 'general', NULL, NULL, NULL, NULL, NULL, '2026. 7. 13.(월) ~ 7. 27.(월) 18:00까지 / 10일간 (주말 제외)', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'local_gov'),
('제19회 은천장학회 장학생 선발', '은천장학회', '미자립교회 교역자 자녀, 선교사 자녀, 대안학교 재학생 등 학업성적은 우수하나 재정지원이 필요한 고등·대학·대학원 재학생을 대상으로 하는 은천장학회 장학생 선발 공고', NULL, 'euncheon.org', NULL, 35, NULL, NULL, NULL, NULL, 3.15, 'semester', NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-07-14', '고등, 대학, 대학원 재학생', NULL, NULL, 'general', NULL, NULL, NULL, NULL, NULL, '2026. 7. 1.(수) ~ 7. 14.(화) 18:00까지', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'private_foundation'),
('2026년도 세종이도인재장학금(디딤돌장학사업 학자금대출 관련분야 - 원금상환, 이자지원)', '세종연구원', '2026년도 세종이도인재장학금 디딤돌장학사업 학자금대출 관련분야(원금상환, 이자지원) 신청 공고. 세종특별자치시 1년이상 계속 거주자(본인 또는 부·모) 중 한국장학재단에서 학자금 대출을 받은 자 대상, 분야별 상이. 신청방법: 이메일(jh@sri.re.kr) 제출', NULL, NULL, NULL, NULL, NULL, '세종', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-08-31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026. 7. 6.(월) ~ 8. 31.(월), 18:00까지', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'local_gov'),
('2027년 청년능력개발지원사업 일본어학연수 학비지원', '엔젤루트국제교류장학회', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'private_foundation'),
('2026년 미래이음 장학금', '제주평생교육장학진흥원', '제주4·3유족, 독립유공자 증손·고손을 대상으로 하는 2026년 미래이음 장학금 장학생 추가모집. 자세한 사항은 모집 공고문 참조.', 5000000, NULL, NULL, NULL, NULL, '제주', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['national_merit'], '{}', '{}', '2026-07-15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '총 100명 이내', '2026. 7. 1.(수) ~ 7. 15.(수)', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'local_gov'),
('2026학년도 "대학생 청소년 AI 교육지원사업" 멘토 모집 안내', '한국장학재단', '한국장학재단에서 지원하는 대학생 청소년교육지원사업의 멘토를 모집. 전국 초·중·고등학교, 교육청 자체 운영기구(센터) 등에서 활동하며, 어린이집·유치원·노인복지시설 등은 활동 불가. 추천 및 공개모집 후 면접을 통해 최종선발하며, AI·SW 공과대학 재학생(컴퓨터융합학부, 게임소프트웨어공학과, AI응용학과 등)은 면접 시 추가점수 부여. 대학생 근로장학사업(국가근로장학금, 대학생 청소년교육지원장학금, 다문화·탈북학생 멘토링장학금, 대학생 청소년 AI 교육지원장학금) 내 중복참여 불가.', NULL, 'http://www.kosaf.go.kr', NULL, NULL, NULL, NULL, NULL, NULL, 3.15, NULL, NULL, NULL, 'korean_only', NULL, NULL, '{}', '{}', '{}', '2026-07-10', '재학생 (신입생, 편입생은 성적 제한 없음)', NULL, NULL, 'general', 'AI·SW 공과대학 재학생(컴퓨터융합학부, 게임소프트웨어공학과, AI응용학과 등) 면접 진행 시 추가점수 부여', NULL, NULL, NULL, '4명', '2026. 7. 3.(금) ~ 2026. 7.10.(금)', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'support_fund', 'activity_participation_support'),
('2026 부마민주항쟁기념재단 장학생 모집', '부마민주항쟁기념재단', '부마민주항쟁 피해자 및 관련자의 초등학생 이상 (유)손자녀, 민주화운동 관련자의 청소년 이상 (유)자녀, 시민사회운동 활동가의 청소년 이상 자녀, 기타 장학금 지급이 합당하다고 인정되는 자를 대상으로 하며, 4년제/전문대 무관하고 입학예정자 또는 휴학생(복학 예정자) 신청 가능. 접수는 이메일(PDF파일)로 진행.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-07-17', '입학예정자 또는 휴학생(복학 예정자) 신청 가능', NULL, NULL, 'general', NULL, NULL, NULL, NULL, NULL, '2026.7.13.(월) ~ 2026.7.17.(금)', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'private_foundation'),
