('2026년 2학기 농림축산식품부 청년창업농장학생 선발', '농림축산식품부(농어촌희망재단)', '첨부파일(2026년 2학기 농림축산식품부(청년창업농장학금) 장학생 선발공고.hwp)로 공고된 청년창업농장학생 선발 안내이며, 본문에는 공고 게시글 정보만 있고 세부 자격요건은 첨부파일에 있어 본문에서 확인 불가.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-06-30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '~6.30.', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'private_foundation'),
('제35회 사회복지법인 사랑의날개 장학지원사업', '사회복지법인 사랑의날개', '저소득 장애인 대학생을 대상으로 하는 장학지원사업으로, 사용목적 제약 없이 지원됨. 접수는 우편으로 진행.', 1000000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, ARRAY['near_poor'], '{}', '{}', '2026-07-01', NULL, NULL, NULL, 'general', NULL, NULL, NULL, NULL, '총 10명', '2026. 6. 1(월) ~ 7. 1(수) (7.1 소인유효)', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'private_foundation'),
('2026학년도 지역인재장학금', '한국장학재단', '지역인재의 수도권 유출 완화 및 지역대학의 자율적인 인재 유치기회 확대를 통해 차별화된 발전 유도를 목적으로 하는 장학금. 비수도권 고교 졸업자이며 소득구간 9구간 이하의 신입생 중 성적우수유형(수시: 고3 1학기까지 이수과목 중 1/2 이상 3등급 이내, 정시: 수능 2개 영역 이상 3등급 이내) 또는 특성화유형(학과별 추천)에 해당하는 자를 선발. 소득구간 0~6구간은 전 학기 지원, 7~9구간은 1년(2개 학기) 지원.', NULL, 'https://forms.gle/ptvGJpyBJNZNSEHq8', NULL, NULL, NULL, '비수도권', NULL, 9, 2.6, 'semester', NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', NULL, '신입생', NULL, NULL, 'general', NULL, '직전학기 취득학점 12학점 이상', 12, '(수시) 고등학교 3학년 1학기까지 이수한 과목 중 1/2 이상이 3등급 이내 / (정시) 수능 2개 영역 이상 3등급 이내', '우리대학에 배정된 지역인재장학금 유형별 예산한도 내에서 선발', NULL, NULL, NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_external', 'national_scholarship'),
('2026-2학기 주거안정장학금 1차 신청 안내', '한국장학재단', '한국장학재단의 기초생활수급자·차상위계층 대상 주거안정장학금 1차 신청 안내 공고. 세부 신청 방법은 첨부된 통합신청 매뉴얼(홈페이지용/모바일용) 참고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['basic_livelihood_recipient','near_poor'], '{}', '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '~6.22.', NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'national_scholarship'),
('국가근로장학금 (2026년 2학기 1차)', '한국장학재단', '2026년 2학기 1차 국가근로장학금 학생신청 안내. 국가근로장학금은 소속대학이 확정된 학생만 신청 가능하며, 소속대학이 미정인 신(편)입생은 2차 학생신청기간을 이용해야 함. 2026년 동계방학 집중근로 프로그램 참여 희망 학생은 2학기 학생신청기간(1차 또는 2차)에 반드시 신청 필요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-06-22', NULL, NULL, NULL, 'general', NULL, NULL, NULL, NULL, NULL, '2026. 5. 22.(금) 9시 ~ 2026. 6. 22.(월) 18시까지', '목원대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'national_scholarship'),
('국내 외국인 근로자 자녀 장학금', '산학협동재단', '국내에 거주하는 외국인 근로자 자녀에게 장학금을 지원하여 안정적인 국내 정착 및 우수한 외국인 인적자원 유입으로 국내 산업계에 기여하기 위한 장학사업. 반드시 대학(총장 명의)의 추천을 받아 공문과 함께 접수해야 하며 개별(개인) 접수는 불가함.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['multicultural_family'], '{}', '{}', '2026-07-17', NULL, NULL, NULL, 'general', NULL, NULL, NULL, NULL, NULL, '공고일부터 2026. 7. 17.(금) 17시까지 (도착분에 한함)', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'private_foundation'),
('2026년도 산학재단 디딤돌 장학금', '산학협동재단', '경제적으로 어려움을 겪고 있는 대학 신입생을 대상으로 자신의 꿈과 학업에 집중할 수 있도록 대학 재학 중 全 학년 장학금 지원하여 국가와 사회에 이바지하는 인재로 양성. 반드시 대학(총장 명의)의 추천을 받아 공문과 함께 접수해야 하며 개별(개인) 접수 불가.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['financial_emergency'], '{}', '{}', '2026-07-17', '국내 4년제 대학 신입생(2026학년도 1학년 재학생)', NULL, '의학계열 등 5~6년 교육과정 학과(부)', 'general', NULL, NULL, NULL, NULL, NULL, '공고일부터 2026. 7. 17.(금) 17시까지 (도착분에 한함)', NULL, NULL, 'undergrad_enrolled', 1, 1, NULL, 'school_external', 'private_foundation'),
('2026년도 상반기 강화군 대학생 등록금 지원사업', '강화군', '강화군 대학생 등록금 지원사업 공고로, 붙임 파일(공고문 hwpx)에 세부 내용이 있으며 본문에는 첨부파일 안내만 게시됨', NULL, NULL, NULL, NULL, NULL, '강화군', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-05-27', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'support_fund', NULL),
('2026-1학기 국가근로장학금 하계방학 집중근로 프로그램', '한국장학재단', '집중근로 프로그램은 하계방학 기간동안 교외근로기관에서 집중적으로 근로를 진행하는 프로그램이며, 한국장학재단 우선 추천 대상자 안내 및 대학 예산 상황에 따라 선발 진행됨.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, NULL, NULL, NULL, NULL, 'korean_only', NULL, NULL, '{}', '{}', '{}', '2026-05-29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '한국장학재단 우선 추천 대상 안내 및 예산 상황에 따라 선발인원 결정', '2026. 05. 20.(수)~2026. 05. 29.(금) ~18:00', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'national_scholarship'),
('2026년 2학기 국가장학금 1차 신청 안내', '한국장학재단', '재학생, 신입생, 편입생, 재입학생, 복학생 등 모든 재학생을 대상으로 하는 2026년 2학기 국가장학금 1차 신청 안내. 신청 후 부모 및 배우자 명의 공인인증서 등을 통한 온라인 동의와 서류제출이 필요하며, 학생 본인 명의로 신청해야 하고 학자금 지원구간 산정에 약 8주 내외 소요됨.', NULL, 'http://www.kosaf.go.kr', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-06-22', NULL, NULL, NULL, 'general', NULL, NULL, NULL, NULL, NULL, '2026. 5. 22.(금) 9시 ~ 6. 22.(월) 18시', NULL, NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'national_scholarship'),
('2026년 1학기 거창군 지역출신 대학생 등록금 지원사업', '거창군', '거창군 지역출신 대학생을 대상으로 한 등록금 지원사업 공고. 상세 내용은 첨부 공고문(pdf) 참조.', NULL, NULL, NULL, NULL, NULL, '거창군', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-06-15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'support_fund', 'youth_living_support'),
('2026년도 신화 장학생 선발', '신화장학재단', '대전시 소재 공과대학 재학생 중 저소득층(사회배려계층으로 기초생활수급, 차상위계층, 본인 또는 부모장애 등)으로 학비 조달이 어려운 자 중 성적 우수자를 대상으로 학업보조비(생활비)를 지급. 지원 분야별 관련 학과: 건축, 토목, 기계, 전기, 통신, 소방, 조경. 제출서류는 모집요강 확인 필요.', NULL, NULL, NULL, NULL, NULL, '대전', NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, ARRAY['basic_livelihood_recipient','near_poor'], '{}', '{}', '2026-05-28', NULL, '건축학부,도시공학과,도시·환경·화학공학과,전기전자공학과,소방방재학과', NULL, 'general', '대전시 소재 공과대학', NULL, NULL, NULL, NULL, '~5.28(목)까지', NULL, '공과대학', 'undergrad_enrolled', NULL, NULL, NULL, 'school_external', 'private_foundation'),
('2026년 화성시인재육성재단 「해외유학 장학금」', '화성시인재육성재단', '', NULL, NULL, NULL, NULL, NULL, '화성시', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'school_external', 'local_gov'),
('2026 파란사다리사업 학생선발 추가모집', '목원대학교', '경제/사회적 취약계층 대학생을 대상으로 해외연수 경험을 제공하며 글로벌 역량 개발 및 진로 개척 기회를 열어주고 사회진출 이전 동일한 출발점을 맞춰주는 교육 사다리 체계 구축. 2026년 하계방학 중 4주간 해외파견 프로그램 참여비용 전액 지원(단, 현지 생활비 본인 부담이며, 유류할증료는 추후 본인 부담이 발생할 수 있음). 지원 가능 국가: 태국, 베트남(미국은 추가 지원 불가). 대학별 추천인원 2인 이내.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2026-05-15', NULL, NULL, NULL, 'general', NULL, NULL, NULL, NULL, '대학별 2인 이내 추천, 최종 선발 가능 인원 범위 내 추가 모집', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'support_fund', 'activity_participation_support'),
('2026년 국가우수장학금 이공계 신규장학생 재학중우수자유형(2년 지원)', '한국장학재단', '국가우수장학생(이공계)으로 선발된 이력이 없는 자연과학 및 공학계열 학과(부) 3학년 재학생을 대상으로 대학 자체 선발기준(총평균성적 50점 + 대회공모전 수상 30점 + 경제적수준 10점 + 사회공헌활동 계획 10점)에 의거하여 고득점자순으로 선발. 최종선발된 학생은 한국장학재단에 온라인 신청 필요. 동일학기에 한국장학재단에서 운영 중인 타 장학금(대통령과학장학금, 인문100년장학금, 예술체육비전장학금, 전문기술인재장학금, 국가장학금, 중소기업 취업연계 장학금, 고졸 후학습자 장학금) 수혜자 또는 장학생 자격 유지자는 신청 불가.', NULL, 'https://forms.gle/yFK1NigfsTcCnERr7', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, 'cumulative', NULL, NULL, NULL, NULL, NULL, '{}', '{}', '{}', '2025-05-22', '3학년 재학생', '자연과학 및 공학계열 학과(부)', NULL, 'general', NULL, '총 이수학점이 졸업이수학점 기준의 40% 이상 충족', NULL, NULL, NULL, '2025. 5. 12.(화) ~ 5. 22.(금)까지', NULL, NULL, 'undergrad_enrolled', 3, 3, NULL, 'school_external', 'national_scholarship');
